package jacamo.checkpoint;

import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;

/** Hashes of the reviewed source overlays, generated by their reproducible build. */
public final class CheckpointBuildIdentity {
    private static final Properties pinned=load();
    private CheckpointBuildIdentity(){ }
    private static Properties load(){
        var properties=new Properties();
        try(var stream=CheckpointBuildIdentity.class.getResourceAsStream("/META-INF/checkpoint-binaries.properties")){
            if(stream!=null)properties.load(stream);
        }catch(java.io.IOException failure){throw new IllegalStateException("CHECKPOINT_BINARY_LOCK_UNREADABLE",failure);}
        return properties;
    }
    public static boolean supports(String component,Class<?> type){
        try {
            Path source=Path.of(type.getProtectionDomain().getCodeSource().getLocation().toURI());
            if(!Files.isRegularFile(source))return false;
            String hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(source)));
            return hash.equals(pinned.getProperty(component));
        }catch(Exception unavailable){return false;}
    }
    public static boolean complete(){return Complete.value;}
    private static final class Complete {private static final boolean value=inspectComplete();}
    private static boolean inspectComplete(){
        return supports("runtime",org.jacamo.checkpoint.runtime.ExecutionBarrier.class)
                &&supports("cartago",cartago.Artifact.class)&&supports("cartago",cartago.Workspace.class)
                &&supports("npl",npl.NPLInterpreter.class)&&supports("npl",npl.TimeTerm.class)
                &&supports("jason",jason.infra.local.LocalAgArch.class)&&supports("jason",jason.stdlib.wait.class);
    }
}
